    /** @param list<UsageEventSpec> $specs @return array{imported:int, duplicates:int} */
    public function import(array $specs): array
    {
        if ($specs === []) return ['imported' => 0, 'duplicates' => 0];
        return $this->em->wrapInTransaction(function (): array {
            $providers = []; $requestIds = [];
