                $entity->tokensOutput = $spec->tokensOutput;
                $entity->tokensCacheRead = $spec->tokensCacheRead;
                $entity->tokensCacheWrite = $spec->tokensCacheWrite;
                $this->em->persist($entity);
                $imported++;
            }
            $this->em->flush();
            return ['imported' => $imported, 'duplicates' => $duplicates];
