```php
final class Rater
{
    private const CHUNK_SIZE = 500;

    public function __construct(
        private readonly EntityManagerInterface $em,
        private readonly UsageEventRepository $events,
        private readonly PriceRowRepository $priceRows,
        private readonly CostCalculator $calculator,
    ) {}

    public function rateAll(): RateResult
    {
        return $this->em->wrapInTransaction(function (): RateResult {
            $rated = 0; $unrated = [];
            int $afterId = 0;
            while (true) {
                $chunk = $this->events->findNotRated(self::CHUNK_SIZE, $afterId);
                if ($chunk === []) break;
                $afterId = $chunk[count($chunk) - 1]->id; // ascending sort — max id

                $rowsByPair = [];
                $providerByCode = [];
                foreach ($chunk as $event) {
                    $pair = $event->provider . "\0" . $event->model;
                    if (!isset($rowsByPair[$pair])) {
                        $rowsByPair[$pair] = $this->priceRows->findAllFor($event->provider, $event->model);
                    }
                    if (!isset($providerByCode[$event->provider])) {
                        $providerByCode[$event->provider] = $this->em->getRepository(Provider::class)->findOneBy(['code' => $event->provider]);
                    }
                }

                foreach ($chunk as $event) {
                    $pair = $event->provider . "\0" . $event->model;
                    $chosen = null;
                    foreach ($rowsByPair[$pair] as $row) {
                        if ($row->validFrom <= $event->ts) { $chosen = $row; }  // ascending sort → the last one satisfying the condition
                        else break;
                    }
                    if ($chosen === null) {
                        $event->status = EventStatus::Unrated;
                        $unrated[] = $event;
                        continue;
                    }
                    $offPeak = $providerByCode[$event->provider]?->offPeak();
                    $event->status = EventStatus::Rated;
                    $event->priceRowId = $chosen->id;
                    $event->billedCost = $this->calculator->eventCost(
                        new TokenUsage($event->tokensInput, $event->tokensOutput, $event->tokensCacheRead, $event->tokensCacheWrite),
                        new PriceRowValue(
                            $chosen->provider->code,
                            $chosen->model->code,
                            $chosen->validFrom,
                            $chosen->currency,
                            PriceUnit::from($chosen->unit),
                            $this->ratesOf($chosen),
                        ),
                        $event->ts,
                        $offPeak,
                    );
                    $rated++;
                }

                $this->em->flush();
            }
            return new RateResult($rated, \count($unrated), $unrated);
        });
    }

    /** @return array<TokenKind, string> */
    private function ratesOf(PriceRow $row): array
    {
        return array_filter([
            TokenKind::Input => $row->rateInput,
            TokenKind::Output => $row->rateOutput,
            TokenKind::CacheRead => $row->rateCacheRead,
            TokenKind::CacheWrite => $row->rateCacheWrite,
            TokenKind::Any => $row->rateAny,
        ], static fn (?string $rate): bool => $rate !== null);
    }
}
